using System.Text.Json;
using Microsoft.Extensions.Configuration;
var file=Path.Combine(Path.GetTempPath(),"feedback-tests-"+Guid.NewGuid()+"/feedback.db");
var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Feedback:Database",file},{"ConnectionStrings:Feedback",Environment.GetEnvironmentVariable("SIYUE_FEEDBACK_TEST_POSTGRES")}}).Build();
var store=new Store(config);var user=new Actor(Guid.NewGuid().ToString(),"验收教师","teacher");var other=new Actor(Guid.NewGuid().ToString(),"其他教师","teacher");var admin=new Actor(Guid.NewGuid().ToString(),"验收管理员","admin");int count=0;
JsonElement J(object value)=>JsonSerializer.SerializeToElement(value);
void Assert(bool ok,string label){if(!ok)throw new Exception(label);count++;}
void Denied(Action fn,int status,string label){try{fn();throw new Exception(label+": unexpectedly allowed");}catch(Fault e){Assert(e.Status==status,label);}}
string Request()=>Guid.NewGuid().ToString();
string key=new('a',64),key2=new('b',64);
var req=Request();var ticket=J(store.Create(user,key,req,"选择班级时页面一直加载","校区前台","{}"));var id=Guid.Parse(ticket.GetProperty("id").GetString()!);
Assert(J(store.Detail(id,user,key)).GetProperty("ticket").GetProperty("body").GetString()=="选择班级时页面一直加载","owner can view");
Denied(()=>store.Detail(id,other,key),404,"other account cannot use same device key");
Denied(()=>store.Detail(id,null,key),404,"guest key cannot access named user");
Assert(J(store.Detail(id,admin,"" )).GetProperty("ticket").GetProperty("id").GetString()==id.ToString(),"admin can view");
Assert(J(store.Create(user,key,req,"选择班级时页面一直加载","校区前台","{}")).GetProperty("id").GetString()==id.ToString(),"create retry idempotence");
Denied(()=>store.Create(user,key,req,"different","校区前台","{}"),409,"changed retry rejected");
Denied(()=>store.Reply(id,other,key,"恶意回复",Request()),404,"cross user reply denied");
var replyKey=Request();store.Reply(id,admin,"","已收到，请补充浏览器版本。",replyKey);store.Reply(id,admin,"","已收到，请补充浏览器版本。",replyKey);
Assert(J(store.Detail(id,user,key)).GetProperty("replies").GetArrayLength()==1,"reply retry creates one reply");
Assert(J(store.Detail(id,user,key)).GetProperty("ticket").GetProperty("status").GetString()=="processing","admin reply enters processing");
Denied(()=>store.ChangeStatus(id,user,key,"processing"),403,"owner cannot assign admin state");
store.ChangeStatus(id,admin,"","verify");store.ChangeStatus(id,user,key,"resolved");
Assert(J(store.Detail(id,user,key)).GetProperty("ticket").GetProperty("status").GetString()=="resolved","owner confirms resolved");
store.Reply(id,user,key,"问题还在",Request());Assert(J(store.Detail(id,user,key)).GetProperty("ticket").GetProperty("status").GetString()=="open","user followup reopens");
var img1=J(store.Image(id,user,key,new byte[]{1,2,3},"image/png"));
Assert(J(store.Image(id,user,key,new byte[]{1,2,3},"image/png")).GetProperty("id").GetString()==img1.GetProperty("id").GetString(),"image retry deduplicated");
store.Image(id,user,key,new byte[]{2,3,4},"image/png");store.Image(id,user,key,new byte[]{3,4,5},"image/png");Denied(()=>store.Image(id,user,key,new byte[]{4,5,6},"image/png"),400,"three image cap");
Denied(()=>store.Image(id,other,key,new byte[]{9},"image/png"),404,"other user cannot attach image");
Denied(()=>store.ReadImage(Guid.NewGuid(),Guid.Parse(img1.GetProperty("id").GetString()!)),404,"image bound to ticket");
var anonymous=J(store.Create(null,key,Request(),"无法登录","","{}"));var guestId=Guid.Parse(anonymous.GetProperty("id").GetString()!);
Assert(J(store.Detail(guestId,null,key)).GetProperty("ticket").GetProperty("name").GetString()=="未登录用户","guest can submit and view");Denied(()=>store.Detail(guestId,null,key2),404,"different device blocked");
Assert(J(store.List(other,key2,false,null,0)).GetProperty("items").GetArrayLength()==0,"list isolates other user");
Assert(J(store.List(user,key,false,null,0)).GetProperty("items").GetArrayLength()==2,"user sees own and this device guest");
Assert(J(store.List(admin,"",true,null,0)).GetProperty("items").GetArrayLength()==2,"admin lists all");
var context=Check.Context(JsonDocument.Parse("{\"page\":\"/workbench/?token=private#secret\",\"error\":\"password=secret bearer abc\",\"password\":\"never store\"}").RootElement);
Assert(!context.Contains("private")&&!context.Contains("never store")&&!context.Contains("secret")&&!context.Contains("abc"),"context strips URL secrets and unlisted fields");
var parallelRequest=Request();var results=await Task.WhenAll(Enumerable.Range(0,10).Select(_=>Task.Run(()=>J(store.Create(other,key2,parallelRequest,"网络重试","","{}")).GetProperty("id").GetString())));
Assert(results.Distinct().Count()==1,"parallel retry creates one ticket");
var persisted=new Store(config);Assert(J(persisted.Detail(id,user,key)).GetProperty("images").GetArrayLength()==3,"data survives reopening");
for(int i=0;i<19;i++)store.Create(other,key2,Request(),"频率测试","","{}");Denied(()=>store.Create(other,key2,Request(),"频率测试","","{}"),429,"hourly submission cap");
Console.WriteLine(JsonSerializer.Serialize(new{passed=count,database=file}));
